const sum=a=>a.reduce((v,x)=>v+total(x),0);
const total=x=>Math.round(x.lines.reduce((a,l)=>a+l.qty*l.price*(1+l.tax/100),0)*100)/100;
const net=x=>Math.round(x.lines.reduce((a,l)=>a+l.qty*l.price,0)*100)/100;
const age=x=>Math.max(0,Math.floor((CLOCK-new Date(x.since))/86400000));
const who=x=>x.status==='route'||x.status==='approval'?'Selin Yılmaz':x.status==='branch'||x.status==='issue'?PEOPLE[PROJECTS.indexOf(x.project)]||'Şube ataması bekleniyor':'—';
const badge=x=>`<span class="badge ${STATUS[x.status][1]}">${STATUS[x.status][0]}</span>`;
const line=(name,qty,unit,price,tax,category,received=qty)=>({name,qty,unit,price,tax,category,received});
